flashWire:{title:'FLASH: LIVE WIRE',glyph:'ϟ',color:'#ffe875',desc:'Critical chance +6 % and fire rate +10%.',action:()=>{player.critChance=Math.min(.75,(player.critChance||0)+.06);player.fireRate*=1.10;build.push('Flash: Live Wire')}},ember:{title:'EMBER: PYRE CASCADE',glyph:'♨',color:'#ff9c65',rarity:'rare',desc:`RARE · Burn potency +15% per rank (rank ${player.pyreCascade||0} → ${Math.min(3,(player.pyreCascade||0)+1)}).`,action:()=>{player.pyreCascade=Math.min(3,(player.pyreCascade||0)+1);player.burnMult=(player.burnMult||1)*1.15;build.push('Ember: Pyre Cascade '+player.pyreCascade)}},frost:{title:'FROST: CRYSTAL RESONANCE',glyph:'❄',color:'#8cecff',rarity:'rare',desc:`RARE · +2 armor and +3 % critical chance per rank (rank ${player.crystalResonance||0} → ${Math.min(3,(player.crystalResonance||0)+1)}).`,action:()=>{player.crystalResonance=Math.min(3,(player.crystalResonance||0)+1);player.armor=Math.min(60,(player.armor||0)+2);player.critChance=Math.min(.6,(player.critChance||0)+.03);build.push('Frost: Crystal Resonance '+player.crystalResonance)}},nova:{title:'AETHER: GRAVITATIONAL LENS',glyph:'◉',color:'#fff7cf',rarity:'rare',desc:`RARE · Black-hole radius +12% and collapse damage +12% per rank (rank ${player.prismaticOverdrive||0} → ${Math.min(3,(player.prismaticOverdrive||0)+1)}).`,action:()=>{player.prismaticOverdrive=Math.min(3,(player.prismaticOverdrive||0)+1);player.aetherWellRadiusBonus=(player.aetherWellRadiusBonus||0)+.12;player.aetherCollapseMult=(player.aetherCollapseMult||1)*1.12;build.push('Aether: Gravitational Lens '+player.prismaticOverdrive)}},
